These kernels come from a CUDA training codebase we are bringing up on MI300X with HIP. On our H100s everything passes. Review them for what will go wrong on MI300X and write findings to review.md. Assume warp-size and mask issues are already handled elsewhere; focus on what is left. Don't build or run anything.

```cpp
// (1) per-block partial sums, last block finishes the reduction
__global__ void bias_grad(const float* dout, float* partial, unsigned* flag, float* dbias, int N, int C) {
  extern __shared__ float acc[];            // C floats
  for (int c = threadIdx.x; c < C; c += blockDim.x) acc[c] = 0.f;
  __syncthreads();
  for (int r = blockIdx.x; r < N; r += gridDim.x)
    for (int c = threadIdx.x; c < C; c += blockDim.x) acc[c] += dout[r * C + c];
  __syncthreads();
  for (int c = threadIdx.x; c < C; c += blockDim.x) partial[blockIdx.x * C + c] = acc[c];
  __syncthreads();
  __shared__ unsigned last;
  if (threadIdx.x == 0) last = atomicInc(flag, gridDim.x);
  __syncthreads();
  if (last == gridDim.x - 1)
    for (int c = threadIdx.x; c < C; c += blockDim.x) {
      float s = 0.f;
      for (int b = 0; b < gridDim.x; b++) s += partial[b * C + c];
      dbias[c] = s;
    }
}

// host
int blocks = prop.maxThreadsPerMultiProcessor * prop.multiProcessorCount / 512;
assert(blocks <= 1024);   // a later 1024-thread kernel reduces one value per block

size_t smem = 10 * C * sizeof(float);   // C is 768 in tests, up to 4096 in production
cudaError_t st = cudaFuncSetAttribute(ln_fwd_big, cudaFuncAttributeMaxDynamicSharedMemorySize, smem);
cudaCheck(cudaGetLastError());
if (st == cudaSuccess) ln_fwd_big<<<grid, 256, smem>>>(...);
else ln_fwd_small<<<grid2, 256>>>(...);
```

We're bringing this CUDA reduction up on an MI300X with HIP; it passes on our A100 CI for every block size we launch (32, 64, 128, 256). Review it for anything that will break on the MI300X and write your findings to review.md. Don't build or run anything.

```cpp
template <class T> __device__ T warpReduceSum(unsigned long long mask, T v) {
  for (int off = warpSize / 2; off > 0; off /= 2) v += __shfl_down_sync(mask, v, off);
  return v;
}

template <class T, unsigned blockSize>
__global__ void reduce(const T* in, T* out, unsigned n) {
  T s = 0;
  for (unsigned i = blockIdx.x * blockSize + threadIdx.x; i < n; i += blockSize * gridDim.x) s += in[i];
  const unsigned long long mask = blockSize >= 64 ? ~0ull : ((1ull << blockSize) - 1);
  s = warpReduceSum(mask, s);
  __shared__ T partial[32];
  if (threadIdx.x % warpSize == 0) partial[threadIdx.x / warpSize] = s;
  __syncthreads();
  if (threadIdx.x < warpSize) {
    s = threadIdx.x < (blockSize + warpSize - 1) / warpSize ? partial[threadIdx.x] : 0;
    s = warpReduceSum(mask, s);
    if (threadIdx.x == 0) out[blockIdx.x] = s;
  }
}
```

